-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'INTRODUCAO TIC' and a.numero = 6
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 6 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 06', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 06 (10 questões discursivas)',
      '/MATERIAIS/ASSISTENTE-DE-OPERACOES-LOGISTICAS/INTRODUCAO-TIC/ATIVIDADES/ATIVIDADE-PRATICA-AULA-06.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Informe o tamanho do papel e as quatro margens no padrão ABNT e explique por que a margem esquerda é maior.', 0.5, 'Papel A4 (210 × 297 mm). Margens ABNT: superior 3 cm, esquerda 3 cm, inferior 2 cm, direita 2 cm. A esquerda é maior para sobrar espaço para a encadernação ou os grampos sem cobrir o texto.', 'Nota cheia: A4 + as quatro margens certas + motivo da esquerda. Metade: margens com um erro ou sem o motivo. Zero: margens erradas.'),
      (v_atividade, 1, 2, 'Explique qual orientação usar no texto e na tabela larga do anexo e o que é preciso inserir para mudar a orientação só no anexo.', 0.5, 'Texto em orientação retrato; a tabela larga do anexo em paisagem. Para mudar só o anexo, inserir uma quebra de seção (próxima página) antes do anexo e aplicar a orientação paisagem só nessa seção.', 'Nota cheia: retrato/paisagem + quebra de seção. Metade: orientações certas sem a quebra de seção (ou cita quebra de página). Zero: sem relação.'),
      (v_atividade, 2, 1, 'Escolha a fonte e o tamanho do corpo do texto e explique a diferença de uso entre fonte com serifa e sem serifa.', 0.5, 'Fonte legível, sem enfeites, como Arial ou Calibri tamanho 12 (ou Times 12 para impresso, no padrão da empresa). Fonte com serifa (Times) é tradicional em impressos; sem serifa (Arial) é mais legível em telas.', 'Nota cheia: fonte e tamanho adequados + diferença serifa/sem serifa. Metade: só um dos dois. Zero: mantém fonte decorativa.'),
      (v_atividade, 2, 2, 'Explique como destacar termos-chave e termos estrangeiros e por que não se deve usar o sublinhado como destaque.', 0.5, 'Negrito para termos-chave e alertas importantes; itálico para estrangeirismos ("picking", "cross-docking"). Não usar sublinhado porque o leitor confunde com link (hiperlink); cor só com moderação, pois some na impressão em preto e branco.', 'Nota cheia: negrito + itálico + motivo do sublinhado. Metade: dois desses. Zero: um ou nenhum.'),
      (v_atividade, 3, 1, 'Indique o alinhamento, o espaçamento entre linhas, o recuo de primeira linha e o espaçamento após o parágrafo que você usaria, e onde fica o alinhamento centralizado.', 0.5, 'Texto justificado, entrelinha 1,5, recuo de primeira linha de 1,25 cm e espaçamento de 6 pt depois do parágrafo. Centralizado só na capa, nos títulos especiais e nas legendas, não no corpo do texto.', 'Nota cheia: justificado + 1,5 + recuo + espaço após + uso do centralizado. Metade: três ou quatro desses. Zero: dois ou menos.'),
      (v_atividade, 3, 2, 'Explique por que apertar Enter várias vezes para separar parágrafos é um erro e como fazer do jeito certo.', 0.5, 'Vários Enters criam parágrafos vazios: a formatação fica desigual, quebra quando o texto muda e é amadora. O certo é configurar o espaçamento "Depois" (ou "Antes") do parágrafo em Formatar/Parágrafo.', 'Nota cheia: problema + espaçamento Depois. Metade: só um dos dois. Zero: concorda com os Enters.'),
      (v_atividade, 4, 1, 'Explique quais estilos aplicar aos capítulos e às subseções e a vantagem de usar estilos em vez de formatar cada título à mão.', 0.5, 'Capítulos (1 Objetivo, 2 Responsabilidades, 3 Etapas, 4 Registros) com o estilo Título 1; subseções 3.1 e 3.2 com Título 2. Os estilos padronizam todos os títulos, permitem mudar todos de uma vez (alteração global), criam a navegação e o sumário automático.', 'Nota cheia: Título 1/Título 2 corretos + vantagem. Metade: só um dos dois. Zero: formatação manual.'),
      (v_atividade, 4, 2, 'Descreva, em ordem, os passos para inserir o sumário automático e o que fazer depois de mudar o texto ou as páginas.', 0.5, '1) Marcar os títulos com os estilos. 2) Pôr o cursor na página do sumário. 3) Referências → Sumário → sumário automático (no Docs/LibreOffice: Inserir → Sumário/Índice). 4) Depois de mudar o texto ou as páginas, clicar em Atualizar Sumário.', 'Nota cheia: passos na ordem + atualizar. Metade: insere o sumário sem atualizar ou sem os estilos. Zero: sumário digitado.'),
      (v_atividade, 5, 1, 'Explique a diferença entre quebra de página e quebra de seção e onde usar cada uma neste documento.', 0.5, 'Quebra de página leva o texto para a próxima folha mantendo a formatação: usar antes de cada capítulo. Quebra de seção cria uma parte independente (margem, orientação, cabeçalho, numeração): usar depois da capa/sumário (numeração diferente) e antes do anexo em paisagem.', 'Nota cheia: diferença + onde usar cada uma. Metade: só a diferença ou só os usos. Zero: confunde as duas.'),
      (v_atividade, 5, 2, 'Indique o que vai no cabeçalho e no rodapé e explique como esconder o número na capa.', 0.5, 'Cabeçalho: logotipo e nome da empresa (e título do documento). Rodapé: numeração e "Documento interno — uso restrito". Para esconder o número da capa: quebra de seção depois da capa e "Desvincular do anterior" (ou "Primeira página diferente"), deixando a numeração só a partir da seção seguinte.', 'Nota cheia: conteúdo do cabeçalho e do rodapé + como esconder na capa. Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 6, 1, 'Explique quando usar lista numerada, lista com marcadores e lista multinível, aplicando às etapas e aos EPIs.', 0.5, 'Lista numerada para passos em ordem (as etapas do recebimento); marcadores para itens equivalentes sem ordem (os EPIs); multinível para tópicos com subníveis (1.1, 1.1.1), como as etapas com subetapas.', 'Nota cheia: os três tipos com aplicação correta. Metade: dois tipos. Zero: um ou nenhum.'),
      (v_atividade, 6, 2, 'Descreva como configurar a tabela: cabeçalho repetido nas páginas, alinhamento de textos e números e bordas.', 0.5, 'Marcar a primeira linha como cabeçalho que se repete no topo de cada página; textos (produto) alinhados à esquerda e números (quantidade, peso) à direita ou pela vírgula decimal; bordas leves (linhas horizontais sutis), sem grade pesada; sombreamento leve no cabeçalho.', 'Nota cheia: cabeçalho repetido + alinhamentos + bordas. Metade: dois desses. Zero: um ou nenhum.'),
      (v_atividade, 7, 1, 'Explique qual disposição de imagem usar para o layout não se desmontar e como deve ser a legenda de figuras e diagramas.', 0.5, 'Disposição "Alinhado com o texto" (ou "Quadrado") para a imagem não se mover quando o texto muda. Legenda com número e título acima (ex.: "Figura 1 — Empilhamento correto de paletes") e a fonte abaixo; vale também para o diagrama.', 'Nota cheia: disposição estável + legenda com número, título e fonte. Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 7, 2, 'Explique como montar a caixa de ATENÇÃO com bordas e sombreamento e os cuidados para que ela continue legível na impressão.', 0.5, 'Selecionar o parágrafo do aviso e aplicar borda em volta (Bordas e Sombreamento) e sombreamento suave, com a palavra ATENÇÃO em negrito. Cuidados: usar com moderação, tons claros e contraste que funcione na impressão em preto e branco.', 'Nota cheia: borda + sombreamento + cuidado de legibilidade. Metade: dois desses. Zero: um ou nenhum.'),
      (v_atividade, 8, 1, 'Explique como trocar o nome da empresa em todo o documento de uma vez e como fazer o corretor parar de marcar os termos técnicos corretos.', 0.5, 'Usar Localizar e Substituir (Ctrl+U no Word em português ou Ctrl+H): localizar "Vale Sul Distribuidora", substituir por "Distribuidora Vale Sul Logística", Substituir tudo. Para os termos técnicos: definir o idioma português do Brasil e adicionar "WMS", "romaneio" e "picking" ao dicionário personalizado (e conferir a autocorreção).', 'Nota cheia: Localizar e Substituir + dicionário personalizado. Metade: só um dos dois. Zero: trocar um por um.'),
      (v_atividade, 8, 2, 'Indique o modo de exibição para conferir o resultado impresso e o cuidado com a pré-visualização antes de imprimir (linhas órfãs e viúvas, escala).', 0.5, 'Modo Layout de impressão (e a Visualização de impressão). Antes de imprimir, conferir a pré-visualização: evitar linhas órfãs e viúvas (linhas isoladas no topo ou no pé da página), escala em 100% e margens para frente e verso, para não desperdiçar papel.', 'Nota cheia: modo correto + dois cuidados. Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 9, 1, 'Explique como funciona o Controle de Alterações e o que a supervisora faz com cada mudança.', 0.5, 'Ligar o Controle de Alterações (Revisão → Controlar Alterações; no Docs, modo Sugestão): cada inclusão, exclusão e formatação fica marcada com o nome de quem fez. A supervisora revisa cada mudança e aceita ou rejeita uma a uma, mantendo a auditoria.', 'Nota cheia: como funciona + aceitar/rejeitar. Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 9, 2, 'Escreva um exemplo de comentário respeitoso e específico sobre um trecho do procedimento e diga o que fazer com ele depois do ajuste.', 0.5, 'Ex.: "Sugiro incluir no item 3.1 o prazo para registrar a divergência no WMS (até 30 minutos após a descarga), para evitar atraso no lançamento. O que acha?" Específico, educado e com motivo. Depois do ajuste, marcar o comentário como Resolvido.', 'Nota cheia: comentário específico e cordial + resolver. Metade: comentário vago ou sem resolver. Zero: comentário ofensivo ou sem relação.'),
      (v_atividade, 10, 1, 'Escreva o nome padronizado do arquivo final e explique quando usar .docx, .odt, .pdf e um modelo (.dotx/.ott).', 0.5, 'Ex.: 2026-10-07_Procedimento_Recebimento_Carga_v01.pdf (e o editável com o mesmo nome em .docx). .docx: editável, padrão de mercado; .odt: editável em formato aberto; .pdf: versão final para distribuir, sem edição; modelo .dotx/.ott: base padronizada para os procedimentos de todo mês.', 'Nota cheia: nome padronizado (data, assunto, versão) + uso dos quatro formatos. Metade: nome ou formatos incompletos. Zero: nome genérico e sem formatos.'),
      (v_atividade, 10, 2, 'Explique por que enviar a versão final em PDF e os riscos de enviar o .docx com comentários internos.', 0.5, 'O PDF mantém fontes, margens e tabelas iguais em qualquer tela, evita alterações acidentais ou indevidas e facilita remover metadados. Enviar o .docx com comentários internos pode vazar informações estratégicas ou pessoais (LGPD), permitir adulterar o conteúdo e prejudicar a imagem da empresa.', 'Nota cheia: duas vantagens do PDF + riscos do .docx. Metade: só um dos dois. Zero: sem relação.');
end $$;
